# Missing genotype calls: the regime no bundled fixture had.
#
# Every bundled .bed carries EXACTLY ZERO missing calls (7 files, ~150 million
# calls, verified by decoding them), so `--maxMissing`, `--impute_method`,
# `--dosage_zerod_cutoff`, `--dosage_zerod_MAC_cutoff` and `--is_imputed_data`
# had no golden and no test. `extdata/input/genotype_100markers_missing.*` is
# generated by `harness/tools/make_missing_fixture.py` (byte-reproducible from
# that script alone) and this file pins what the options do to it.
#
# These are INVARIANTS over the shape of the answer -- which markers survive,
# which differ from which -- not a second copy of the goldens. The goldens
# themselves (P42-P48) are re-run by test-step2-goldens.R.

MISS_BASE <- "./input/genotype_100markers_missing"
MISS_ARGS <- function() {
  c(paste0("--bedFile=", MISS_BASE, ".bed"),
    paste0("--bimFile=", MISS_BASE, ".bim"),
    paste0("--famFile=", MISS_BASE, ".fam"),
    "--AlleleOrder=alt-first")
}
MISS_PGEN_ARGS <- function() {
  c(paste0("--pgenFile=", MISS_BASE, ".pgen"),
    paste0("--pvarFile=", MISS_BASE, ".pvar"),
    paste0("--psamFile=", MISS_BASE, ".psam"),
    "--AlleleOrder=alt-first")
}
miss_model <- function() {
  c(paste0("--GMMATmodelFile=",
           file.path(saige_goldens, "step1", "binary_sparseGRM_a.rda")),
    paste0("--varianceRatioFile=",
           file.path(saige_goldens, "step1", "binary_sparseGRM_a.varianceRatio.txt")))
}
MISS_COMMON <- c("--chrom=1", "--minMAF=0", "--minMAC=1", "--LOCO=FALSE",
                 "--is_output_moreDetails=TRUE")

# One run per option setting, cached per process so the ~7 CLI invocations are
# not repeated by every expectation below.
miss_cache <- new.env(parent = emptyenv())
miss_run <- function(key, extra = character(), geno = MISS_ARGS()) {
  if (!is.null(miss_cache[[key]])) return(miss_cache[[key]])
  out <- file.path(tempfile("miss_"), paste0(key, ".txt"))
  dir.create(dirname(out), recursive = TRUE)
  status <- run_saige_cli("step2_SPAtests.R",
                          c(geno, miss_model(), MISS_COMMON, extra,
                            paste0("--SAIGEOutputFile=", out)))
  expect_cli_ok(status)
  miss_cache[[key]] <- read_saige_table(out)
  miss_cache[[key]]
}

# Markers the FIXTURE GENERATOR says must behave a particular way. Hard-coded
# here on purpose: if the generator's ladder is edited these must be updated
# with it, and a silent drift is exactly what a fixture test is for.
AF_GE_QUARTER_PASSING <- c("rs23", "rs26", "rs64", "rs66", "rs94", "rs97")
MAC_LE_10_PASSING <- c("rs3", "rs13", "rs16", "rs32", "rs34", "rs35", "rs42",
                       "rs44", "rs45", "rs46", "rs55", "rs56", "rs62", "rs65",
                       "rs72", "rs74", "rs76", "rs77", "rs84", "rs85")
LADDER_PASSING <- c(0, 0.001, 0.005, 0.01, 0.05, 0.1, 0.15)
LADDER_DROPPED <- c(0.151, 0.3, 0.6)

# Markers whose PRINTED value moved in any shared column. read_saige_table
# returns every column as character on purpose (it preserves the "NA"/"nan"
# spellings the goldens carry), so compare the printed strings -- which is also
# the right question for a golden: did this cell's output change. An earlier
# version gated on is.numeric() and therefore compared nothing at all, and
# silently returned "no markers differ" for every pair.
differing_markers <- function(a, b) {
  k <- intersect(a$MarkerID, b$MarkerID)
  x <- a[match(k, a$MarkerID), , drop = FALSE]
  y <- b[match(k, b$MarkerID), , drop = FALSE]
  shared <- setdiff(intersect(names(x), names(y)), "MarkerID")
  moved <- Reduce(`|`, lapply(shared, function(cl) x[[cl]] != y[[cl]]),
                  init = rep(FALSE, length(k)))
  sort(k[moved])
}

test_that("the reported missing rate is the ladder, computed over the MODEL's samples", {
  skip_unless_level("standard")
  skip_if_no_goldens()
  d <- miss_run("base")
  # The denominator is the analysed subset (1,000), not the .fam's 10,000. Every
  # marker also carries 500 missing calls OUTSIDE that subset; if any of them
  # leaked into the count these values would not be on the ladder at all. That
  # is the whole point of the decoys -- a sample-subsetting check, the defect
  # class of LEDGER #52.
  expect_setequal(sort(unique(d$MissingRate)), LADDER_PASSING)
})

test_that("the --maxMissing gate is a STRICT >, so 0.15 passes and 0.151 does not", {
  skip_unless_level("standard")
  skip_if_no_goldens()
  d <- miss_run("base")
  wide <- miss_run("maxmiss1", "--maxMissing=1")
  expect_true(0.15 %in% d$MissingRate)          # exactly at the default cutoff
  expect_false(any(d$MissingRate > 0.15))
  expect_setequal(sort(unique(wide$MissingRate)), c(LADDER_PASSING, LADDER_DROPPED))
  # every marker the gate dropped comes back, and nothing else changes
  gained <- setdiff(wide$MarkerID, d$MarkerID)
  expect_gt(length(gained), 0)
  expect_true(all(wide$MissingRate[match(gained, wide$MarkerID)] > 0.15))
  expect_equal(length(differing_markers(d, wide)), 0)
})

test_that("best_guess and minor differ exactly where round(2*AF) is 1", {
  skip_unless_level("standard")
  skip_if_no_goldens()
  bg <- miss_run("base")
  mi <- miss_run("minor", "--impute_method=minor")
  # imputeG is round(2*AF) for best_guess and 0 for minor (src/UTIL.cpp:83-97),
  # so they can only differ where AF >= 0.25.
  expect_equal(differing_markers(bg, mi), sort(AF_GE_QUARTER_PASSING))
})

test_that("--dosage_zerod_cutoff silently undoes MEAN imputation below the MAC cutoff", {
  skip_unless_level("standard")
  skip_if_no_goldens()
  on_  <- miss_run("mean", "--impute_method=mean")
  off_ <- miss_run("mean_nozerod", c("--impute_method=mean", "--dosage_zerod_cutoff=0"))
  # `t_GVec.clean(cutoff)` runs whenever MAC <= --dosage_zerod_MAC_cutoff (10 by
  # default). Mean imputation writes 2*AF, which on those markers is ~0.003 --
  # below the 0.2 default -- so it is zeroed straight back to what `minor` would
  # have given. Documented as applying "if is_imputed_data = TRUE"; the code
  # never consults that flag. See LEDGER.
  expect_equal(differing_markers(on_, off_), sort(MAC_LE_10_PASSING))
  mi <- miss_run("minor", "--impute_method=minor")
  expect_equal(length(differing_markers(on_[on_$MarkerID %in% MAC_LE_10_PASSING, ],
                                        mi[mi$MarkerID %in% MAC_LE_10_PASSING, ])), 0)
})

test_that("--is_imputed_data REPLACES MissingRate with an always-1 imputationInfo", {
  skip_unless_level("standard")
  skip_if_no_goldens()
  d <- miss_run("base")
  im <- miss_run("imputed", "--is_imputed_data=TRUE")
  # It is a SWAP, not an addition: all four writer sites branch on
  # t_isImputation to emit imputationInfo INSTEAD OF MissingRate
  # (src/Main.cpp:4197, :4258, :4539, :4790), so turning the flag on COSTS the
  # missing rate. Assert the removal as well as the addition -- checking only
  # setdiff(new, old) is what hid this in the first place, and the file being
  # SMALLER than its twin is what gave it away. See LEDGER #107/#108.
  expect_equal(setdiff(names(im), names(d)), "imputationInfo")
  expect_equal(setdiff(names(d), names(im)), "MissingRate")
  expect_equal(length(names(im)), length(names(d)))
  expect_equal(which(names(im) == "imputationInfo"), which(names(d) == "MissingRate"))
  # Both readers assign t_imputeInfo = 1 unconditionally (src/PLINK.cpp:312,
  # src/PGEN.cpp:585), so the replacement column is a constant and --minInfo is
  # a switch at 1 rather than a quality filter. Characterization, not endorsement.
  expect_equal(unique(im$imputationInfo), "1")   # character: see read_saige_table
  # every column they still share is untouched
  expect_equal(length(differing_markers(d, im)), 0)
  expect_equal(im$MarkerID, d$MarkerID)
})

test_that("the PGEN reader agrees with the PLINK reader on missing calls", {
  skip_unless_level("standard")
  skip_if_no_goldens()
  # Every earlier PGEN mirror ran on data with no missing call to disagree
  # about. Counts and labels exactly, statistics at ~1e-12: two readers are two
  # PATHS, so byte-identity is not the thing to assert here (CLAUDE.md).
  a <- miss_run("base")
  b <- miss_run("pgen_base", geno = MISS_PGEN_ARGS())
  expect_equal(a$MarkerID, b$MarkerID)
  expect_equal(a$MissingRate, b$MissingRate)
  expect_equal(a$AC_Allele2, b$AC_Allele2)
  expect_equal(a$p.value, b$p.value, tolerance = 1e-12)
  expect_equal(a$BETA, b$BETA, tolerance = 1e-12)
})
